WITH items(kind,name,x1,x2,x3,x4,definition) AS (SELECT 'schema',name,NULL,NULL,NULL,NULL,sql FROM sqlite_schema WHERE type IN ('table','view') AND name IN ('t1a','t2a','t3a','t4a','t1b','t2b','t3b','t4b','t1','t2','t3','t4') UNION ALL SELECT 'data','t1a',a,b,c,d,NULL FROM t1a UNION ALL SELECT 'data','t2a',c,d,e,f,NULL FROM t2a UNION ALL SELECT 'data','t3a',a,b,e,f,NULL FROM t3a UNION ALL SELECT 'data','t4a',a,c,d,f,NULL FROM t4a UNION ALL SELECT 'data','t1b',a,b,c,d,NULL FROM t1b UNION ALL SELECT 'data','t2b',c,d,e,f,NULL FROM t2b UNION ALL SELECT 'data','t3b',a,b,e,f,NULL FROM t3b UNION ALL SELECT 'data','t4b',a,c,d,f,NULL FROM t4b UNION ALL SELECT 'data','t1',a,b,c,d,NULL FROM t1 UNION ALL SELECT 'data','t2',c,d,e,f,NULL FROM t2 UNION ALL SELECT 'data','t3',a,b,e,f,NULL FROM t3 UNION ALL SELECT 'data','t4',a,c,d,f,NULL FROM t4) SELECT kind,name,x1,x2,x3,x4,definition FROM items ORDER BY kind,name,x1 NULLS FIRST,x2 NULLS FIRST,x3 NULLS FIRST,x4 NULLS FIRST,definition NULLS FIRST;